select fpa.PRD_DESIGN_ID prdDesignId,DATE_FORMAT(PAY_DATE,'%m') as assetMonth,sum(curEndAmt) curEndAmt from ( select ZCCC.FINPROD_ID FINPROD_ID, FIN_CASH_PLAN.PAY_DATE PAY_DATE,ZCCC.PORTFOLIO_ID PORTFOLIO_ID, (case when FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType_bond} then round(ZCCC.AMOUNT*FIN_CASH_PLAN.PRIN_AMT,2) when IFNULL(FIN_PRODUCT.ISSUE_AMT,0) - IFNULL(YHBFX.PAID_AMT,0) = 0 then 0 else round(ZCCC.AMOUNT*FIN_CASH_PLAN.PRIN_AMT/(IFNULL(FIN_PRODUCT.ISSUE_AMT,0) - IFNULL(YHBFX.PAID_AMT,0)),2) end) curEndAmt from ( SELECT SUM(A.AMOUNT) AMOUNT, A.FINPROD_ID FINPROD_ID, A.PORTFOLIO_ID PORTFOLIO_ID FROM PTL_SEC_POSITION A LEFT JOIN FIN_PRODUCT_TYPE B ON A.FINPROD_ID = B.FINPROD_ID WHERE A.HODING_TYPE = #{holdingType,jdbcType=VARCHAR}
and A.CDATE = STR_TO_DATE(#{cdate}, '%Y-%m-%d')
and B.TYPE_9 IN
#{item}
and B.TYPE_10 IN
#{item}
and B.TYPE_11 IN
#{item}
and B.TYPE_12 IN
#{item}
group by A.FINPROD_ID,A.PORTFOLIO_ID ) ZCCC JOIN FIN_CASH_PLAN ON ZCCC.FINPROD_ID = FIN_CASH_PLAN.FINPROD_ID JOIN FIN_PRODUCT ON ZCCC.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN ( select sum(PRIN_AMT) PAID_AMT,FINPROD_ID from FIN_CASH_PLAN where FIN_CASH_PLAN.MDATE <=STR_TO_DATE(#{benchDate}, '%Y-%m-%d') and FIN_CASH_PLAN.CASH_TYPE in ('02','03') group by FIN_CASH_PLAN.FINPROD_ID ) YHBFX on ZCCC.FINPROD_ID = YHBFX.FINPROD_ID where FIN_CASH_PLAN.PAY_DATE >=STR_TO_DATE(#{benchDate}, '%Y-%m-%d') and FIN_CASH_PLAN.PAY_DATE <=STR_TO_DATE(#{benchDateEnd}, '%Y-%m-%d') and ZCCC.AMOUNT !=0 and FIN_CASH_PLAN.CASH_TYPE in ('02','03') ) TEMP INNER JOIN FIN_PRODUCT_ADD fpa ON fpa.PORTFOLIO_ID = TEMP.PORTFOLIO_ID INNER JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = fpa.FINPROD_ID AND fp.FINPROD_TYPE2 = #{finprodType2} AND fp.P_FINPROD_ID is null group by DATE_FORMAT(PAY_DATE,'%m'),fpa.PRD_DESIGN_ID
